def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * size]
    failure = [0]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            index = char_index[ch]
            if transitions[state][index] == -1:
                transitions[state][index] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                terminal.append(False)
            state = transitions[state][index]
        terminal[state] = True

    queue = deque()
    for index in range(size):
        child = transitions[0][index]
        if child == -1:
            transitions[0][index] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for index in range(size):
            child = transitions[state][index]
            if child == -1:
                transitions[state][index] = transitions[failure[state]][index]
            else:
                failure[child] = transitions[failure[state]][index]
                queue.append(child)

    safe_states = [state for state in range(len(transitions)) if not terminal[state]]
    state_index = {state: index for index, state in enumerate(safe_states)}
    count = len(safe_states)

    matrix = [[0] * count for _ in range(count)]
    for state in safe_states:
        row = matrix[state_index[state]]
        for destination in transitions[state]:
            if not terminal[destination]:
                row[state_index[destination]] += 1

    vector = [0] * count
    vector[state_index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        if weight:
                            result[j] = (result[j] + value * weight) % mod
            vector = result

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, left in enumerate(matrix[i]):
                    if left:
                        for j, right in enumerate(matrix[k]):
                            if right:
                                squared[i][j] = (squared[i][j] + left * right) % mod
            matrix = squared

    return sum(vector) % mod
